import {initPhotoFit} from './photo-ui.js';
import {defaults,definitions,sanitize,toOBJ} from './model.js';
import {studioDefaults,sanitizeStudio} from './character.js';
import {poseDefaults,clamp,poseAt} from './rig.js';
import {Viewer} from './viewer.js';
import {toGLB,characterOBJ} from './glb.js';
const $=s=>document.querySelector(s),canvas=$('#canvas');let viewer;
try{viewer=new Viewer(canvas);}catch(e){$('#status').textContent=e.message;throw e;}
let params={...defaults},studio={...studioDefaults},pose={...poseDefaults},mode='body',mesh=null,yaw=.25,pitch=0,zoom=1.02,wire=false,multi=false,seq=0,worker=null,timer,working=false,playing=false,activeClip='none',time=0,animation=0,lastFrame=0,referenceURL=null;
const visibility={body:true,head:true,hair:true};
try{params=sanitize(JSON.parse(localStorage.getItem('form-settings')||'{}'));studio=sanitizeStudio(JSON.parse(localStorage.getItem('form-studio')||'{}'));}catch{}
function notice(s){$('#studio-notice').textContent=s;}
function expression(){return [studio.blink,studio.smile,studio.mouthOpen];}
function draw(){viewer.render({mode,yaw,pitch,zoom,multi,visibility,pose,clip:activeClip,time,expression:expression()});}
new ResizeObserver(draw).observe(canvas);
function ranges(container,rows,state,prefix,change){for(const[k,name,min,max,step]of rows){const l=document.createElement('label');l.className='param';l.innerHTML=`<span>${name}<output id="${prefix}-o-${k}"></output></span><input aria-label="${name}" id="${prefix}-${k}" type="range" min="${min}" max="${max}" step="${step}">`;container.append(l);l.querySelector('input').addEventListener('input',e=>{state()[k]=Number(e.target.value);change();sync();});}}
for(const [title,rows]of definitions){const h=document.createElement('h2');h.textContent=title;$('#controls').append(h);ranges($('#controls'),rows,()=>params,'p',schedule);}
const hairRows=[['hairVolume','髪のボリューム',.85,1.25,.01],['hairLength','髪の長さ',0,1,.01],['fringe','前髪の長さ',0,1,.01]],expRows=[['blink','まばたき',0,1,.01],['smile','笑顔',0,1,.01],['mouthOpen','口を開く',0,1,.01]],poseRows=[['headTurn','顔を左右に向ける',-50,50,1],['armRaise','左腕を上げる',0,100,1],['elbowBend','左肘を曲げる',0,100,1],['kneeBend','左膝を曲げる',0,85,1]],matRows=[['roughness','表面の粗さ',0,1,.01]];
ranges($('#hair-controls'),hairRows,()=>studio,'s',schedule);ranges($('#expression-controls'),expRows,()=>studio,'s',()=>{stop();draw();});ranges($('#pose-controls'),poseRows,()=>pose,'r',()=>{stop();draw();});ranges($('#material-controls'),matRows,()=>studio,'s',schedule);
function sync(){for(const k in defaults){$('#p-'+k).value=params[k];$('#p-o-'+k).textContent=k==='height'?Math.round(params[k]*100)+' cm':params[k].toFixed(2);}for(const row of [...hairRows,...expRows,...matRows]){const k=row[0];$('#s-'+k).value=studio[k];$('#s-o-'+k).textContent=studio[k].toFixed(2);}for(const k in pose){$('#r-'+k).value=pose[k];$('#r-o-'+k).textContent=pose[k]+'°';}$('#hair-style').value=studio.hairStyle;$('#skin-color').value=studio.skinColor;$('#hair-color').value=studio.hairColor;try{localStorage.setItem('form-settings',JSON.stringify(params));localStorage.setItem('form-studio',JSON.stringify(studio));}catch{}}
function schedule(){clearTimeout(timer);timer=setTimeout(rebuild,220);setBusy(true);}
function setBusy(b){working=b;$('#export').disabled=b||!mesh;$('#export-glb').disabled=b||!mesh?.rig;$('#snapshot').disabled=b||!mesh;}
function rebuild(){clearTimeout(timer);stop();setBusy(true);$('#status').textContent='キャラクターを生成中…';worker?.terminate();worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});const id=++seq;
 worker.onmessage=({data})=>{if(data.id!==seq)return;if(data.error){$('#status').textContent='生成エラー: '+data.error;mesh=null;setBusy(false);return;}mesh=data.mesh;viewer.setMesh(mesh,wire);setBusy(false);const count=mesh.parts?mesh.parts.reduce((n,p)=>n+p.indices.length/3,0):mesh.vertices.length/9;$('#status').textContent=count.toLocaleString()+' triangles'+(mesh.rig?' · 17関節 · 表情3種類':' · 等値面モデル');const advanced=!!mesh.rig;for(const name of ['parts','motion','finish'])document.querySelector(`[data-tab="${name}"]`).disabled=!advanced;notice(advanced?'':'髪・表情・ポーズ・GLBは「実データ基準」で使えます。');draw();worker.terminate();worker=null;};
 worker.onerror=()=>{$('#status').textContent='生成に失敗しました。密度を下げて再試行してください。';mesh=null;setBusy(false);};worker.postMessage({params,studio,res:Number($('#quality').value),face:$('#source').value==='data'?false:mode==='face',source:$('#source').value,id});}
function download(value,name,type){const u=URL.createObjectURL(value instanceof Blob?value:new Blob([value],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
$('#export').onclick=()=>{if(!mesh||working)return;const sample=poseAt(pose,activeClip,time,expression());const selected=mesh.parts?{...mesh,parts:mesh.parts.filter(p=>mode!=='face'||p.group!=='body')}:mesh;download(mesh.rig?characterOBJ(selected,{...pose},sample.expression,sample.rotations):toOBJ(mesh),'form-'+mode+'.obj','text/plain');notice('OBJを書き出しました。');};
$('#export-glb').onclick=async()=>{if(!mesh?.rig||working)return;$('#export-glb').disabled=true;notice('GLBを書き出しています…');await new Promise(r=>requestAnimationFrame(r));try{const glb=toGLB({...mesh,studio},pose);download(glb,'form-character.glb','model/gltf-binary');notice('GLBを書き出しました。全パーツ・骨格・表情・2つのモーションを含みます。');}catch(e){notice('書き出し失敗: '+e.message);}finally{$('#export-glb').disabled=false;}};
$('#save').onclick=()=>download(JSON.stringify({version:2,params,studio,pose},null,2),'form-settings.json','application/json');
function cleanPose(value={}){return Object.fromEntries(poseRows.map(([k,,lo,hi])=>[k,Number.isFinite(value[k])?clamp(value[k],lo,hi):0]));}
$('#load').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('設定は1MB以下のJSONを選んでください');const d=JSON.parse(await f.text());if(![1,2].includes(d.version)||!d.params)throw Error('対応していない設定形式です');params=sanitize(d.params);studio=sanitizeStudio(d.studio);pose=cleanPose(d.pose);sync();rebuild();notice('設定を読み込みました。');}catch(err){notice('読込できません: '+err.message);}e.target.value='';};
$('#reset').onclick=()=>{params={...defaults};studio={...studioDefaults};pose={...poseDefaults};sync();rebuild();};
for(const b of document.querySelectorAll('[data-preset]'))b.onclick=()=>{params={...defaults,...({slender:{shoulders:.9,waist:.84,hips:.96,muscle:.12,legs:1.06},athletic:{shoulders:1.13,waist:.92,muscle:.88}}[b.dataset.preset]||{})};sync();rebuild();};
for(const b of document.querySelectorAll('[data-tab]')){b.setAttribute('aria-controls','panel-'+b.dataset.tab);const panel=document.querySelector(`[data-panel="${b.dataset.tab}"]`);panel.id='panel-'+b.dataset.tab;b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x!==panel);};}
function setView(next){mode=next;zoom=mode==='face'?5.3:1.02;yaw=.15;pitch=0;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));if($('#source').value==='analytic')rebuild();else draw();}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>setView(b.dataset.view);
function facing(angle){yaw=angle;pitch=0;multi=false;$('#quad').classList.remove('active');$('#quad-labels').hidden=true;$('#reference-overlay').hidden=!referenceURL;draw();}
$('#front').onclick=()=>facing(0);$('#side').onclick=()=>facing(Math.PI/2);$('#back').onclick=()=>facing(Math.PI);$('#wire').onclick=()=>{wire=!wire;if(mesh)viewer.setMesh(mesh,wire);$('#wire').classList.toggle('active',wire);draw();};$('#quad').onclick=()=>{multi=!multi;$('#quad').classList.toggle('active',multi);$('#quad-labels').hidden=!multi;$('#reference-overlay').hidden=multi||!referenceURL;draw();};$('#quality').onchange=rebuild;$('#source').onchange=rebuild;
for(const input of document.querySelectorAll('[data-part]'))input.onchange=()=>{visibility[input.dataset.part]=input.checked;draw();};
$('#hair-style').onchange=e=>{studio.hairStyle=e.target.value;sync();rebuild();};for(const [id,key]of [['skin-color','skinColor'],['hair-color','hairColor']])$('#'+id).oninput=e=>{studio[key]=e.target.value;sync();schedule();};
for(const b of document.querySelectorAll('[data-expression]'))b.onclick=()=>{stop();studio.blink=b.dataset.expression==='blink'?1:0;studio.smile=b.dataset.expression==='smile'?.75:0;studio.mouthOpen=0;sync();draw();};
function updateTime(){$('#timeline').value=time;$('#time-label').textContent=time.toFixed(2)+' s';}
function stop(){playing=false;cancelAnimationFrame(animation);$('#play').textContent='再生';activeClip='none';time=0;updateTime();}
function tick(now){if(!playing)return;const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;time=Math.min(3,time+dt);updateTime();draw();if(time>=3){playing=false;$('#play').textContent='再生';return;}animation=requestAnimationFrame(tick);}
$('#play').onclick=()=>{if(playing){playing=false;cancelAnimationFrame(animation);$('#play').textContent='再生';return;}if(time>=3)time=0;activeClip=$('#clip').value;playing=true;lastFrame=performance.now();$('#play').textContent='一時停止';animation=requestAnimationFrame(tick);};$('#stop').onclick=()=>{stop();draw();};$('#clip').onchange=()=>{stop();draw();};$('#timeline').oninput=e=>{playing=false;cancelAnimationFrame(animation);$('#play').textContent='再生';time=Number(e.target.value);activeClip=$('#clip').value;updateTime();draw();};$('#pose-reset').onclick=()=>{stop();pose={...poseDefaults};sync();draw();};document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;cancelAnimationFrame(animation);$('#play').textContent='再生';}});
$('#reference-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>20e6){notice('比較画像は20MB以下を選んでください。');return;}if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL=URL.createObjectURL(f);const img=$('#reference-overlay');img.onload=()=>{img.hidden=multi;$('#reference-clear').disabled=false;notice('参照画像を重ねました。回転・拡大でモデルを合わせられます。');};img.onerror=()=>{clearReference();notice('画像を開けません。JPEGまたはPNGを選んでください。');};img.src=referenceURL;e.target.value='';};
function clearReference(){if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL=null;const img=$('#reference-overlay');img.removeAttribute('src');img.hidden=true;$('#reference-clear').disabled=true;}$('#reference-clear').onclick=clearReference;$('#reference-opacity').oninput=e=>$('#reference-overlay').style.opacity=e.target.value;
$('#snapshot').onclick=()=>{draw();const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const ctx=out.getContext('2d');ctx.fillStyle='#18232d';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(canvas,0,0);if(multi){ctx.fillStyle='#dfebe5';ctx.font=`${Math.max(14,out.width/45)}px sans-serif`;['正面','右側面','背面','左側面'].forEach((s,i)=>ctx.fillText(s,(i%2)*out.width/2+16,Math.floor(i/2)*out.height/2+30));}out.toBlob(blob=>{if(blob)download(blob,'form-'+(multi?'four-views':'preview')+'.png','image/png');else notice('画像の保存に失敗しました。');});};
const pointers=new Map();let pinch=0;canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);pinch=0;};canvas.onpointermove=e=>{const old=pointers.get(e.pointerId);if(!old)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1&&!multi){yaw+=(e.clientX-old[0])*.008;pitch=clamp(pitch+(e.clientY-old[1])*.006,-1.2,1.2);}else if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinch)zoom=clamp(zoom*d/pinch,.5,15);pinch=d;}draw();};for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,e=>{pointers.delete(e.pointerId);pinch=0;});window.addEventListener('blur',()=>{pointers.clear();pinch=0;});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom*Math.exp(-e.deltaY*.001),.5,15);draw();},{passive:false});
$('#analyze').onchange=async e=>{try{const f=e.target.files[0];if(f.size>25e6)throw Error('25MB以下のOBJを選んでください');const rows=(await f.text()).split(/\r?\n/).filter(l=>/^v\s/.test(l)).map(l=>l.trim().split(/\s+/).slice(1,4).map(Number)).filter(v=>v.length===3&&v.every(Number.isFinite));if(rows.length<10)throw Error('頂点が不足しています');let min=Infinity,max=-Infinity;for(const v of rows){min=Math.min(min,v[1]);max=Math.max(max,v[1]);}const h=max-min;if(h<=0)throw Error('Y方向の高さがありません');const report={vertices:rows.length,height:h,sections:[]};for(let i=1;i<20;i++){const y=min+i*h/20,sl=rows.filter(v=>Math.abs(v[1]-y)<h/40);if(sl.length){let xl=Infinity,xh=-Infinity,zl=Infinity,zh=-Infinity;for(const v of sl){xl=Math.min(xl,v[0]);xh=Math.max(xh,v[0]);zl=Math.min(zl,v[2]);zh=Math.max(zh,v[2]);}report.sections.push({heightFraction:i/20,width:(xh-xl)/h,depth:(zh-zl)/h,samples:sl.length});}}$('#analysis').textContent=JSON.stringify(report,null,2);download(JSON.stringify(report,null,2),'mesh-analysis.json','application/json');}catch(err){$('#analysis').textContent=err.message;}};

canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();stop();$('#status').textContent='3D表示が中断されました。ページを再読み込みしてください。';});sync();rebuild();
window.formDebug={get mesh(){return mesh},get working(){return working},get params(){return params},get studio(){return studio}};
initPhotoFit({getState:()=>({params:{...params},source:$('#source').value,mode,side:Math.abs(yaw-Math.PI/2)<.01}),applyState:state=>{clearTimeout(timer);params=sanitize(state.params);$('#source').value=state.source;mode=state.mode;zoom=mode==='face'?5.3:1.02;yaw=state.side?Math.PI/2:0;pitch=0;multi=false;$('#quad-labels').hidden=true;$('#quad').classList.remove('active');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));sync();rebuild();}});
